(* [comment removed for export] *)
Lemma verb_of_short : forall l, (length l < 3)%nat -> verb_of l = 0.
Proof.
  intros [|c [|d [|e l]]] H; cbn [length] in H; try lia; [reflexivity| |]; unfold verb_of;
  repeat (first [ reflexivity
                | progress (rewrite !Bool.andb_false_r)
                | match goal with
                  | |- context [if (c =? ?k) then _ else _] => destruct (c =? k)
                  | |- context [if (d =? ?k) then _ else _] => destruct (d =? k)
                  end ]; cbn).
Qed.

(* [comment removed for export] *)
Ltac fold_addlit :=
  repeat match goal with
  | |- context [Z_to_bv 64 (?a + ?b)] => is_Zlit a; is_Zlit b; let v := eval vm_compute in (a + b) in
        change (Z_to_bv 64 (a + b)) with (Z_to_bv 64 v)
  end.

